import React, { useState } from 'react';

export default function BoxModelDemo() {
  const [boxSizing, setBoxSizing] = useState('border-box');

  return (
    <div style={{ padding: '16px', background: '#0f172a', color: '#f8fafc', fontFamily: 'sans-serif' }}>
      <div style={{ marginBottom: '16px' }}>
        <button 
          onClick={() => setBoxSizing(b => b === 'border-box' ? 'content-box' : 'border-box')}
          style={{ background: '#3b82f6', color: '#fff', border: 'none', padding: '6px 14px', borderRadius: '6px', cursor: 'pointer' }}
        >
          Toggle Sizing: <strong>{boxSizing}</strong>
        </button>
      </div>
      <div style={{
        width: '200px',
        padding: '20px',
        border: '5px solid #60a5fa',
        background: '#1e293b',
        boxSizing: boxSizing
      }}>
        Specified Width: 200px<br />
        Padding: 20px | Border: 5px
      </div>
    </div>
  );
}

