export default function FlexDemo() {
  const [justify, setJustify] = useState('space-between');
  return (
    <div style={{ padding: '16px', background: '#111827', color: '#fff' }}>
      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        {['flex-start', 'center', 'space-between', 'space-around'].map(j => (
          <button key={j} onClick={() => setJustify(j)} style={{ background: justify === j ? '#2563eb' : '#374151', color: '#fff', border: 'none', padding: '4px 10px', borderRadius: '4px' }}>
            {j}
          </button>
        ))}
      </div>
      <div style={{ display: 'flex', justifyContent: justify, alignItems: 'center', background: '#1f2937', padding: '12px', borderRadius: '8px' }}>
        <div style={{ background: '#ef4444', padding: '12px 20px', borderRadius: '4px' }}>1</div>
        <div style={{ background: '#10b981', padding: '12px 20px', borderRadius: '4px' }}>2</div>
        <div style={{ background: '#3b82f6', padding: '12px 20px', borderRadius: '4px' }}>3</div>
      </div>
    </div>
  );
}

