import React, { useState } from 'react';

export default function ClosureApp() {
  const [count, setCount] = useState(0);
  return (
    <div style={{ padding: '16px', background: '#111827', color: '#fff', borderRadius: '8px' }}>
      <h3 style={{ margin: '0 0 8px 0', color: '#60a5fa' }}>Closure State Sandbox</h3>
      <p>Captured Value: <strong>{count}</strong></p>
      <button 
        onClick={() => setCount(c => c + 1)} 
        style={{ background: '#2563eb', color: '#fff', border: 'none', padding: '6px 14px', borderRadius: '6px', cursor: 'pointer' }}
      >
        Increment Counter
      </button>
    </div>
  );
}

